<?php
require_once dirname(__DIR__) . '/core/Controller.php'; require_once dirname(__DIR__) . '/models/Requisition.php';
class RequisitionController extends Controller { private Requisition $model; public function __construct(){ $this->model=new Requisition(); } public function index():void{$this->requireLogin();$this->view('requisitions/index',['title'=>'Requisitions','requisitions'=>$this->model->all()]);} public function create():void{$this->requireLogin();if($_SERVER['REQUEST_METHOD']==='POST'&&$this->validateCsrf())$this->model->create($_POST+['requested_by'=>$_SESSION['user']['id']??null]);$this->redirect('/index.php?controller=requisition');} public function decide():void{$this->requireModuleAccess('requisition', ['Administrator','Procurement Officer','Store Officer']);if($_SERVER['REQUEST_METHOD']==='POST'&&$this->validateCsrf())$this->model->updateStatus($this->sanitizeInt($_POST['id']??0),$this->sanitize($_POST['status']??'pending'),$_SESSION['user']['id']??null,$this->sanitize($_POST['comments']??''));$this->redirect('/index.php?controller=requisition');} }
